import React from "react";
import { createRoot } from "react-dom/client";
import { HatchContextProvider } from "./hatch-context.js";
import {
  createClientRuntime,
  GeneratedSpaceRuntimeProvider,
} from "./runtime.js";
import "./styles.css";

const SPACE_ROOT_SELECTOR = "[data-generated-space-root]";
const SPACE_SLUG_ATTRIBUTE = "data-generated-space-slug";
const SPACE_HYDRATED_ATTRIBUTE = "data-generated-space-hydrated";

function buildBootstrap(slug) {
  return {
    hatchContext: { slug },
  };
}

export function mountGeneratedSpace(container, bootstrap, RenderSpace) {
  const runtime = createClientRuntime(bootstrap);
  const root = createRoot(container);
  root.render(
    React.createElement(
      HatchContextProvider,
      { value: bootstrap.hatchContext },
      React.createElement(
        GeneratedSpaceRuntimeProvider,
        { runtime },
        React.createElement(RenderSpace)
      )
    )
  );

  return () => {
    runtime.destroy();
    root.unmount();
  };
}

function readBootstrap(container) {
  const slug = container.getAttribute(SPACE_SLUG_ATTRIBUTE);
  if (slug == null || slug.length === 0) {
    return null;
  }
  return buildBootstrap(slug);
}

export function bootGeneratedSpace(RenderSpace) {
  if (typeof document === "undefined") {
    return;
  }

  const container = document.querySelector(SPACE_ROOT_SELECTOR);
  if (!(container instanceof Element)) {
    return;
  }
  if (container.getAttribute(SPACE_HYDRATED_ATTRIBUTE) === "true") {
    return;
  }

  const bootstrap = readBootstrap(container);
  if (bootstrap == null) {
    return;
  }

  container.setAttribute(SPACE_HYDRATED_ATTRIBUTE, "true");
  mountGeneratedSpace(container, bootstrap, RenderSpace);
}
